#!/usr/bin/env node
// Which commit did the registry actually publish for this version?
//
// The two-stage release leaves a gap: main can move between publish and
// finalize, and a tag cut at finalize-time HEAD would point at a commit nobody
// published. The durable, signed record of the published source is npm's
// provenance attestation (SLSA v1, generated by Trusted Publishing) — it names
// the exact gitCommit the workflow built from. This script resolves that
// commit, refuses every ambiguity, and prints the SHA alone on stdout so a
// workflow can tag exactly what was published.
//
// Refusals (exit 1, reason on stderr):
//   - any package missing a provenance attestation for the version
//   - provenance naming a different repository
//   - the packages disagreeing on the commit (a torn publish)
//
// Test seam: --from-files <file...> reads attestation documents from disk in
// package order instead of fetching, so the refusal paths are testable offline.

const SCOPE = '@asc-agent'
const PACKAGES = ['runtime', 'bootstrap']
const REPOSITORY = 'https://github.com/colosair/asc'
const PROVENANCE = 'https://slsa.dev/provenance/v1'

export async function resolvePublishedCommit(version, documents) {
  const commits = []
  for (let i = 0; i < PACKAGES.length; i += 1) {
    const name = `${SCOPE}/${PACKAGES[i]}`
    const doc = documents[i]
    if (!doc || !Array.isArray(doc.attestations)) {
      throw new Error(`${name}@${version}: no attestation document — was this version published by the release workflow?`)
    }
    const provenance = doc.attestations.find((a) => a.predicateType === PROVENANCE)
    if (!provenance) {
      throw new Error(`${name}@${version}: no SLSA provenance attestation among [${doc.attestations.map((a) => a.predicateType).join(', ')}]`)
    }
    const payload = JSON.parse(Buffer.from(provenance.bundle.dsseEnvelope.payload, 'base64').toString('utf8'))
    const definition = payload.predicate?.buildDefinition
    const repository = definition?.externalParameters?.workflow?.repository
    if (repository !== REPOSITORY) {
      throw new Error(`${name}@${version}: provenance names ${repository}, expected ${REPOSITORY}`)
    }
    const commit = definition?.resolvedDependencies?.[0]?.digest?.gitCommit
    if (!/^[0-9a-f]{40}$/.test(commit ?? '')) {
      throw new Error(`${name}@${version}: provenance carries no usable gitCommit (${String(commit)})`)
    }
    commits.push({ name, commit })
  }
  const distinct = [...new Set(commits.map((c) => c.commit))]
  if (distinct.length !== 1) {
    throw new Error(`torn publish — the packages name different commits: ${commits.map((c) => `${c.name}=${c.commit.slice(0, 12)}`).join(', ')}`)
  }
  return distinct[0]
}

async function fetchDocuments(version) {
  const documents = []
  for (const pkg of PACKAGES) {
    const url = `https://registry.npmjs.org/-/npm/v1/attestations/${encodeURIComponent(`${SCOPE}/${pkg}`)}@${version}`
    const response = await fetch(url)
    if (!response.ok) {
      throw new Error(`${SCOPE}/${pkg}@${version}: attestation endpoint answered ${response.status}`)
    }
    documents.push(await response.json())
  }
  return documents
}

const isMain = process.argv[1] && import.meta.url.endsWith(process.argv[1].replace(/\\/g, '/').split('/').pop())
if (isMain) {
  const [version, flag, ...files] = process.argv.slice(2)
  if (!version) {
    console.error('usage: resolve-published-commit.mjs <version> [--from-files <file...>]')
    process.exitCode = 1
  } else {
  try {
    const documents =
      flag === '--from-files'
        ? await Promise.all(files.map(async (f) => JSON.parse(await (await import('node:fs/promises')).readFile(f, 'utf8'))))
        : await fetchDocuments(version)
    const commit = await resolvePublishedCommit(version, documents)
    console.log(commit)
  } catch (error) {
    console.error(String(error.message ?? error))
    // exitCode, not exit(): a hard exit races undici's open handles on Windows
    process.exitCode = 1
  }
  }
}
